{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_0cfe2533ddc084e0e79cf479", "claim_ids": ["claim_62240d460debdebe0d751aeb", "claim_65fd3a5a88199dc7f5cb7df9"], "query_ids": ["q_327"], "claims": [{"claim_id": "claim_62240d460debdebe0d751aeb", "quote": "Safety-critical components, including airbags, windshields, mirrors, and seat belts, are among the targeted items.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff", "effective_date": "May 3"}}, {"claim_id": "claim_65fd3a5a88199dc7f5cb7df9", "quote": "Safety-critical components like airbags, mirrors, seats, and batteries will be subject to the same 25% tariff starting May 3.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff", "effective_date": "May 3"}}]}, {"pair_id": "conflict_90dd7faec77181ad89646931", "claim_ids": ["claim_35fa0188bb8f7442a9ffd657", "claim_3e4052016b7c68f36bfa9156"], "query_ids": ["q_327"], "claims": [{"claim_id": "claim_35fa0188bb8f7442a9ffd657", "quote": "President Donald Trump signed an executive order that goes into effect April 2 imposing a 25 percent tariff on cars built outside of the U.S.", "url": "https://digitaldealer.com/news/us-tariff-tracker-impact-automaker-response/164521", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25 percent tariff", "legal_authority": "executive order", "effective_date": "April 2"}}, {"claim_id": "claim_3e4052016b7c68f36bfa9156", "quote": "On March 26, the Trump Administration announced a 25 percent tariff on imports of automobiles and certain automotive parts. The tariff went into effect for fully assembled vehicles on April 3. The tariff on auto parts will go into effect on May 3.", "url": "https://www.asashop.org/2025/04/04/understanding-the-new-tariffs-and-their-potential-impact-on-auto-repairers", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25 percent tariff on imports of automobiles and certain automotive parts", "effective_date": "April 3", "reported_policy_status": "announced"}}]}, {"pair_id": "conflict_da5d3b102298eec3eafaecbc", "claim_ids": ["claim_3c635fb6456af5d96ef59f23", "claim_415e56d153b2e7101f7203a4"], "query_ids": ["q_327"], "claims": [{"claim_id": "claim_3c635fb6456af5d96ef59f23", "quote": "A few weeks ago, President Trump announced a 25% tariff on goods from Mexico and Canada. He followed that announcement by issuing an exemption – expiring April 2 – for autos and auto parts.", "url": "https://www.asashop.org/2025/04/04/understanding-the-new-tariffs-and-their-potential-impact-on-auto-repairers", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_415e56d153b2e7101f7203a4", "quote": "Last week, President Trump granted a one-month exemption on recent tariffs on imports from Mexico and Canada for U.S. automakers.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "U.S. automakers", "tariff_program": "recent tariffs on imports from Mexico and Canada", "effective_date": "one-month exemption"}}]}, {"pair_id": "conflict_ecf6dd76f9b6b817ceff4ef2", "claim_ids": ["claim_3e4052016b7c68f36bfa9156", "claim_5660f160c83adcce52497d18"], "query_ids": ["q_327"], "claims": [{"claim_id": "claim_3e4052016b7c68f36bfa9156", "quote": "On March 26, the Trump Administration announced a 25 percent tariff on imports of automobiles and certain automotive parts. The tariff went into effect for fully assembled vehicles on April 3. The tariff on auto parts will go into effect on May 3.", "url": "https://www.asashop.org/2025/04/04/understanding-the-new-tariffs-and-their-potential-impact-on-auto-repairers", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25 percent tariff on imports of automobiles and certain automotive parts", "effective_date": "April 3", "reported_policy_status": "announced"}}, {"claim_id": "claim_5660f160c83adcce52497d18", "quote": "The White House announced that passenger vehicles, certain trucks, and auto parts will be exempt from the new 10% global tariff set to take effect on February 24, 2026.", "url": "https://digitaldealer.com/news/us-tariff-tracker-impact-automaker-response/164521", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "new 10% global tariff", "effective_date": "February 24, 2026"}}]}, {"pair_id": "conflict_d2704c1cb3943a02716c24c5", "claim_ids": ["claim_0500ac75b01ee29cdde914c3", "claim_bc62a9ffc8da215971654d71"], "query_ids": ["q_328"], "claims": [{"claim_id": "claim_0500ac75b01ee29cdde914c3", "quote": "In August, the US administration extended the scope of the 50% import tariffs for steel and aluminium goods, adding more than 400 additional items to the levy, including car parts such as chassis components, axles, steel wiring, brackets and mounts, and parts of heavy vehicles.", "url": "https://www.automotivelogistics.media/supply-chain/tariff-analysis-deep-dive-the-most-important-changes-for-the-auto-industry/663875", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "50% import tariffs for steel and aluminium goods", "duty_rate": "50%"}}, {"claim_id": "claim_bc62a9ffc8da215971654d71", "quote": "In August, the US administration extended the scope of the 50% import tariffs for steel and aluminium goods, adding more than 400 additional items to the levy, including car parts such as chassis components, axles, steel wiring, brackets and mounts, and parts of heavy vehicles.", "url": "https://www.automotivelogistics.media/supply-chain/tariff-analysis-deep-dive-the-most-important-changes-for-the-auto-industry/663875", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "50% import tariffs for steel and aluminium goods", "affected_product": "car parts such as chassis components, axles, steel wiring, brackets and mounts, and parts of heavy vehicles", "duty_rate": "50%", "announcement_date": "August"}}]}, {"pair_id": "conflict_f53b6436d2ec6c1893a099f7", "claim_ids": ["claim_7b49ad8735108d5143ed01f7", "claim_b1ba152847766d3efe91d8cb"], "query_ids": ["q_328"], "claims": [{"claim_id": "claim_7b49ad8735108d5143ed01f7", "quote": "Trump imposed sweeping 25% tariffs on all steel and aluminum imports on March 12", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Trump", "tariff_program": "sweeping 25% tariffs on all steel and aluminum imports", "duty_rate": "25%", "effective_date": "March 12"}}, {"claim_id": "claim_b1ba152847766d3efe91d8cb", "quote": "Starting March 12, 2025, President Trump is bringing back the full 25% tariff on steel imports. He is also raising tariffs on aluminum imports to 25%.", "url": "https://www.everstream.ai/articles/navigate-tariff-risk-automotive-sc-mapping", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "March 12, 2025"}}]}, {"pair_id": "conflict_f98a18912fdd4778b4c7147d", "claim_ids": ["claim_041d393ef6f27745f181758c", "claim_9328a19861edb7d910932453"], "query_ids": ["q_329"], "claims": [{"claim_id": "claim_041d393ef6f27745f181758c", "quote": "The tariffs on safety parts such as seat belts and airbags create conditions ripe for counterfeiting", "url": "https://www.autonews.com/manufacturing/an-trump-tariffs-safety-airbags-0415", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "tariffs on safety parts such as seat belts and airbags", "affected_product": "seat belts and airbags"}}, {"claim_id": "claim_9328a19861edb7d910932453", "quote": "Safety parts such as airbags, bumpers, seat belts, safety glass, rearview mirrors, and lighting equipment are included in the tariff rollout.", "url": "https://motorillustrated.com/engines-airbags-tires-among-dozens-of-auto-parts-now-subject-to-u-s-import-tariffs/151892", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "airbags, bumpers, seat belts"}}]}, {"pair_id": "conflict_74855e3ad4823d8ded6f5c79", "claim_ids": ["claim_19f4f2691f2dac3aa83fc9cb", "claim_35a7086502cde743177852ce"], "query_ids": ["q_33"], "claims": [{"claim_id": "claim_19f4f2691f2dac3aa83fc9cb", "quote": "this week the Trump Administration announced a 25% tariff on vehicles imported into the us we were there in Georgia just as the news was breaking", "url": "https://www.youtube.com/watch?v=u1XBETuQbVE", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff on vehicles imported into the us", "legal_authority": "Trump Administration"}}, {"claim_id": "claim_35a7086502cde743177852ce", "quote": "On July 30, U.S. President Donald Trump said the U.S. will charge a 15% tariff on imports from South Korea, down from a threatened 25%, and reduce duties on automobile imports to 15% from the current 25%", "url": "https://www.usatoday.com/story/cars/news/2025/09/18/hyundai-production-shift-us-tariffs/86221578007", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "U.S. President Donald Trump said the U.S. will charge a 15% tariff on imports from South Korea", "duty_rate": "15%", "announcement_date": "July 30"}}]}, {"pair_id": "conflict_04d6af20be90d8b4997437b3", "claim_ids": ["claim_35a7086502cde743177852ce", "claim_8b549be3aef0216ba1c79d57"], "query_ids": ["q_33"], "claims": [{"claim_id": "claim_35a7086502cde743177852ce", "quote": "On July 30, U.S. President Donald Trump said the U.S. will charge a 15% tariff on imports from South Korea, down from a threatened 25%, and reduce duties on automobile imports to 15% from the current 25%", "url": "https://www.usatoday.com/story/cars/news/2025/09/18/hyundai-production-shift-us-tariffs/86221578007", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "U.S. President Donald Trump said the U.S. will charge a 15% tariff on imports from South Korea", "duty_rate": "15%", "announcement_date": "July 30"}}, {"claim_id": "claim_8b549be3aef0216ba1c79d57", "quote": "Munoz said the company's revised financial guidance was based on the current 25% U.S. tariff rate, adding that its plan to produce 80% of the vehicles it sells in the United States locally is to reduce tariff exposure and strengthen growth", "url": "https://www.usatoday.com/story/cars/news/2025/09/18/hyundai-production-shift-us-tariffs/86221578007", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}]}, {"pair_id": "conflict_3b5d5ace08f003335b1d5ee9", "claim_ids": ["claim_1d3c0463abe24d8798e50739", "claim_5ad19b243bbd6f93ca25fcf8"], "query_ids": ["q_330"], "claims": [{"claim_id": "claim_1d3c0463abe24d8798e50739", "quote": "Importers of automobiles under the United States-Mexico-Canada Agreement will be given the opportunity to certify their U.S. content and systems will be implemented such that the 25% tariff will only apply to the value of their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "United States-Mexico-Canada Agreement"}}, {"claim_id": "claim_5ad19b243bbd6f93ca25fcf8", "quote": "USMCA-compliant automobile parts will remain tariff-free until the Secretary of Commerce, in consultation with U.S. Customs and Border Protection (CBP), establishes a process to apply tariffs to their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "USMCA", "reported_policy_status": "remain tariff-free"}}]}]}

